            news.subscribe(reader);
            readers[arg] = std::move(reader);
        } else if (command == "leave") {
            readers.erase(arg);
        } else {
            news.publish(arg);
        }
    }
    for (const auto &[name, reader] : readers) {
        std::println("{}: получено {}", name, reader->received);
